import { describe, it, expect } from "vitest";
import { randomUUID } from "node:crypto";
import {
  createIsolatedDatabase,
  databaseTestsEnabled,
} from "./helpers/foundation-db";
const migration = "20261020040000_admin_panel";
describe.runIf(databaseTestsEnabled)(
  "immutable operator audit migration",
  () => {
    it("fails on multiple operators, safely projects legacy events, enforces inserts and permits only FK-triggered nulling", async () => {
      const f = await createIsolatedDatabase();
      try {
        for (const m of f.migrations.filter((m) => m < migration))
          await f.apply(m);
        const actor = randomUUID(),
          target = randomUUID(),
          audit = randomUUID();
        for (const id of [actor, target])
          await f.client.query(
            'INSERT INTO "User" (id,email,"isAdmin") VALUES ($1,$2,true)',
            [id, `${id}@test.local`],
          );
        await f.client.query(
          `INSERT INTO "AdminAuditLog" (id,"actorUserId","targetUserId","actorIdSnapshot","targetIdSnapshot",action,"requestId",reason,before,after) VALUES ($1,$2,$3,$2,$3,'LEGACY-SECRET-ACTION','LEGACY-SECRET-REQUEST','LEGACY-SECRET-REASON','{"body":"LEGACY-SECRET-BODY"}','{"refreshToken":"[REDACTED_SECRET]"}')`,
          [audit, actor, target],
        );
        await expect(f.apply(migration)).rejects.toThrow(
          "ADMIN_SINGLETON_CONFLICT",
        );
        await f.client.query("ROLLBACK");
        await f.client.query('UPDATE "User" SET "isAdmin"=false WHERE id=$1', [
          target,
        ]);
        await f.apply(migration);
        const row = (
          await f.client.query('SELECT * FROM "AdminAuditSafe" WHERE id=$1', [
            audit,
          ])
        ).rows[0];
        expect(row).toMatchObject({
          action: "LEGACY",
          reason: "LEGACY",
          before: {},
          after: {},
          requestId: null,
          requestHash: null,
        });
        expect(JSON.stringify(row)).not.toContain("SECRET");
        await expect(
          f.client.query('UPDATE "User" SET "isAdmin"=true WHERE id=$1', [
            target,
          ]),
        ).rejects.toMatchObject({ code: "23505" });
        for (const sql of [
          "UPDATE \"AdminAuditLog\" SET reason='SUPPORT'",
          'UPDATE "AdminAuditLog" SET "targetUserId"=NULL',
          'DELETE FROM "AdminAuditLog"',
          'TRUNCATE "AdminAuditLog"',
        ])
          await expect(f.client.query(sql)).rejects.toThrow(
            "ADMIN_AUDIT_IMMUTABLE",
          );
        const insert = (
          action: string,
          before: object,
          after: object,
          reason = "SUPPORT",
        ) =>
          f.client.query(
            `INSERT INTO "AdminAuditLog" (id,"actorIdSnapshot",action,"requestId","requestHash",reason,before,after) VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
            [
              randomUUID(),
              actor,
              action,
              randomUUID(),
              "a".repeat(64),
              reason,
              JSON.stringify(before),
              JSON.stringify(after),
            ],
          );
        for (const [action, before, after, reason] of [
          ["SUSPENSION", { isSuspended: false }, { body: "SECRET" }, "SUPPORT"],
          [
            "SUSPENSION",
            { isSuspended: false },
            { isSuspended: true, extra: "SECRET" },
            "SUPPORT",
          ],
          [
            "SUSPENSION",
            { isSuspended: false },
            { isSuspended: true },
            "arbitrary reason",
          ],
          ["UNKNOWN", {}, {}, "SUPPORT"],
          [
            "PLAN_OVERRIDE",
            { planOverride: null, startsAt: null, expiresAt: null },
            { planOverride: "PAID", startsAt: "bad-date", expiresAt: null },
            "SUPPORT",
          ],
        ] as const)
          await expect(insert(action, before, after, reason)).rejects.toThrow(
            "ADMIN_AUDIT_INVALID",
          );
        await insert(
          "SUSPENSION",
          { isSuspended: false },
          { isSuspended: true },
        );
        await f.client.query('DELETE FROM "User" WHERE id=ANY($1)', [
          [actor, target],
        ]);
        const retained = (
          await f.client.query('SELECT * FROM "AdminAuditLog" WHERE id=$1', [
            audit,
          ])
        ).rows[0];
        expect(retained.actorUserId).toBeNull();
        expect(retained.targetUserId).toBeNull();
        expect(retained.actorIdSnapshot).toBe(actor);
        expect(retained.targetIdSnapshot).toBe(target);
        expect(retained.before).toEqual({ body: "LEGACY-SECRET-BODY" });
      } finally {
        await f.cleanup();
      }
    }, 30000);
  },
);
